CREATE TABLE "data_subject_requests" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"subjectEmail" TEXT NOT NULL,"type" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING_VERIFICATION',"scope" JSONB NOT NULL,"reason" TEXT NOT NULL,"ticketId" TEXT NOT NULL,"requestedById" TEXT NOT NULL,"verifiedById" TEXT,"approvedById" TEXT,"identityVerifiedAt" TIMESTAMP(3),"approvedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "data_subject_requests_pkey" PRIMARY KEY ("id"));
CREATE TABLE "privacy_legal_holds" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"subjectEmail" TEXT,"reason" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdById" TEXT NOT NULL,"releasedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"releasedAt" TIMESTAMP(3),CONSTRAINT "privacy_legal_holds_pkey" PRIMARY KEY ("id"));
CREATE TABLE "privacy_download_grants" ("id" TEXT NOT NULL,"requestId" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"consumedAt" TIMESTAMP(3),"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "privacy_download_grants_pkey" PRIMARY KEY ("id"));
CREATE INDEX "data_subject_requests_tenantId_status_createdAt_idx" ON "data_subject_requests"("tenantId","status","createdAt"); CREATE INDEX "data_subject_requests_subjectEmail_createdAt_idx" ON "data_subject_requests"("subjectEmail","createdAt"); CREATE INDEX "privacy_legal_holds_tenantId_subjectEmail_active_idx" ON "privacy_legal_holds"("tenantId","subjectEmail","active"); CREATE UNIQUE INDEX "privacy_download_grants_tokenHash_key" ON "privacy_download_grants"("tokenHash"); CREATE INDEX "privacy_download_grants_requestId_expiresAt_idx" ON "privacy_download_grants"("requestId","expiresAt");
